/// A cell rectangle. On the wire it is the bare array [x, y, w, h];
/// the names exist because rect[2] does not say "width".
class Rect {
  const Rect(this.x, this.y, this.w, this.h);

  final int x;
  final int y;
  final int w;
  final int h;

  /// Total: a short, long or absent array yields zeros rather than throwing.
  factory Rect.fromJson(Object? v) {
    final a = v is List ? v : const <Object?>[];
    int at(int i) => i < a.length && a[i] is num ? (a[i] as num).toInt() : 0;
    return Rect(at(0), at(1), at(2), at(3));
  }

  List<int> toJson() => [x, y, w, h];

  @override
  bool operator ==(Object other) =>
      other is Rect &&
      x == other.x &&
      y == other.y &&
      w == other.w &&
      h == other.h;

  @override
  int get hashCode => Object.hash(x, y, w, h);

  @override
  String toString() => 'Rect($x, $y, $w, $h)';
}

