/// Decodes one server → client message into its class.
///
/// Returns null for an unrecognised `t`. That is the protocol's rule, not a
/// convenience: a server is free to add message types within a version, and a
/// client that threw on the first unknown one would drop the whole socket.
Object? decodeDown(Map<String, Object?> j) {
  switch (j['t']) {
    case Welcome.type:
      return Welcome.fromJson(j);
    case Layout.type:
      return Layout.fromJson(j);
    case Agents.type:
      return Agents.fromJson(j);
    case PaneTitle.type:
      return PaneTitle.fromJson(j);
    case PaneCwd.type:
      return PaneCwd.fromJson(j);
    case PaneAgent.type:
      return PaneAgent.fromJson(j);
    case PaneModes.type:
      return PaneModes.fromJson(j);
    case PaneExited.type:
      return PaneExited.fromJson(j);
    case PaneFrame.type:
      return PaneFrame.fromJson(j);
    case PaneDiff.type:
      return PaneDiff.fromJson(j);
    case Clipboard.type:
      return Clipboard.fromJson(j);
    case Notify.type:
      return Notify.fromJson(j);
    case Title.type:
      return Title.fromJson(j);
    case ErrorMsg.type:
      return ErrorMsg.fromJson(j);
    case Shutdown.type:
      return Shutdown.fromJson(j);
    case UpdateReady.type:
      return UpdateReady.fromJson(j);
    case Theme.type:
      return Theme.fromJson(j);
    case Usage.type:
      return Usage.fromJson(j);
    case Clients.type:
      return Clients.fromJson(j);
    case CmdResult.type:
      return CmdResult.fromJson(j);
  }
  return null;
}

/// Decodes one client → server message into its class.
///
/// Returns null for an unrecognised `t`. That is the protocol's rule, not a
/// convenience: a client is free to add message types within a version, and a
/// client that threw on the first unknown one would drop the whole socket.
Object? decodeUp(Map<String, Object?> j) {
  switch (j['t']) {
    case Init.type:
      return Init.fromJson(j);
    case Key.type:
      return Key.fromJson(j);
    case Mouse.type:
      return Mouse.fromJson(j);
    case Paste.type:
      return Paste.fromJson(j);
    case Image.type:
      return Image.fromJson(j);
    case Resize.type:
      // ignore: deprecated_member_use_from_same_package
      return Resize.fromJson(j);
    case Raw.type:
      // ignore: deprecated_member_use_from_same_package
      return Raw.fromJson(j);
    case Cmd.type:
      return Cmd.fromJson(j);
  }
  return null;
}
